PARTS={'css': "<style>\n  @font-face{font-family:'Inter';font-weight:700;src:url(fonts/Inter-Bold.otf);}\n  @font-face{font-family:'Inter';font-weight:800;src:url(fonts/Inter-ExtraBold.otf);}\n  @font-face{font-family:'Inter';font-weight:900;src:url(fonts/Inter-Black.otf);}\n  @font-face{font-family:'DejaVu Sans Mono';font-weight:400;src:url(fonts/DejaVuSansMono.ttf);}\n  @font-face{font-family:'DejaVu Sans Mono';font-weight:700;src:url(fonts/DejaVuSansMono-Bold.ttf);}\n  html,body{margin:0;padding:0;overflow:hidden;background:#f5efe3;}\n  #stage{position:relative;width:1080px;height:1920px;overflow:hidden;}\n  canvas{position:absolute;left:0;top:0;width:1080px;height:1920px;display:block;}\n  #caption{position:absolute;left:50px;right:50px;top:1390px;text-align:center;font-family:'Inter';font-weight:800;\n    font-size:74px;line-height:1.1;color:#1d1b2a;letter-spacing:-1.5px;-webkit-text-stroke:14px #f5efe3;paint-order:stroke fill;}\n  #caption.night{color:#fff;-webkit-text-stroke:14px #18213a;}\n  #caption span{display:inline-block;margin:0 10px;}\n  .lbl{position:absolute;font-family:'DejaVu Sans Mono';font-size:40px;font-weight:700;color:#1d1b2a;letter-spacing:3px;\n    white-space:nowrap;transform:translate(-50%,-50%);-webkit-text-stroke:8px #f5efe3;paint-order:stroke fill;}\n  .lbl i{display:inline-block;width:16px;height:16px;border-radius:50%;background:currentColor;margin-right:12px;vertical-align:middle;}\n", 'utils': "import * as THREE from 'three';\nconst FPS = 30, DURATION = 46.5;\nconst SC = Number(new URLSearchParams(location.search).get('scale') || 1);\nconst W = Math.round(1080*SC), H = Math.round(1920*SC);\nif (SC !== 1) { const st = document.getElementById('stage'); st.style.transform = `scale(${SC})`; st.style.transformOrigin = '0 0';\n  document.body.style.width = W + 'px'; document.body.style.height = H + 'px'; }\nconst cv = document.getElementById('c'); cv.width = W; cv.height = H;\nconst clamp01 = x => Math.max(0, Math.min(1, x));\nconst seg = (t, a, b) => clamp01((t - a) / (b - a));\nconst eio = x => x < .5 ? 4*x*x*x : 1 - Math.pow(-2*x + 2, 3) / 2;\nconst eout = x => 1 - Math.pow(1 - x, 3);\nconst eback = x => { const c1 = 1.70158, c3 = c1 + 1; return 1 + c3*Math.pow(x-1,3) + c1*Math.pow(x-1,2); };\nconst lerp = (a, b, k) => a + (b - a) * k;\nconst pulse = (t, a, b) => Math.sin(Math.PI * seg(t, a, b));\nconst vis = (t, a, b, f = .25) => Math.min(seg(t, a, a + f), 1 - seg(t, b - f, b));\nconst inW = (t, a, b) => t >= a && t < b;\n\n", 'base': "// ------------------------------------------------ render base (igual que el video de resinas)\nconst canvas = document.getElementById('c');\nconst renderer = new THREE.WebGLRenderer({canvas, antialias:true, preserveDrawingBuffer:true});\nrenderer.setPixelRatio(1); renderer.setSize(W, H, false);\nrenderer.shadowMap.enabled = true; renderer.shadowMap.type = THREE.PCFSoftShadowMap;\nrenderer.outputColorSpace = THREE.SRGBColorSpace;\nconst BG = new THREE.Color('#f5efe3'), BGN = new THREE.Color('#18213a');\nconst scene = new THREE.Scene(); scene.background = BG.clone();\nconst camera = new THREE.PerspectiveCamera(50, 1080/1920, 0.1, 100);\nconst hemi = new THREE.HemisphereLight('#ffffff', '#8a7cff', 1.1); scene.add(hemi);\nconst sun = new THREE.DirectionalLight('#fffaf0', 2.2); sun.position.set(-3, 5, 6); sun.castShadow = true;\nsun.shadow.mapSize.set(2048, 2048); Object.assign(sun.shadow.camera, {left:-6, right:6, top:6, bottom:-6, near:.5, far:30}); sun.shadow.radius = 3;\nscene.add(sun);\nconst frontScene = new THREE.Scene();                 // herramientas: siempre delante de dientes y encías\nconst hemi2 = hemi.clone(); frontScene.add(hemi2);\nconst sun2 = new THREE.DirectionalLight('#fffaf0', 2.2); sun2.position.copy(sun.position); frontScene.add(sun2);\nconst shadowPlane = new THREE.Mesh(new THREE.PlaneGeometry(60, 60), new THREE.ShadowMaterial({color:'#5b4fd6', opacity:.25}));\nshadowPlane.position.z = -2.2; shadowPlane.receiveShadow = true; shadowPlane.userData.noOutline = true; scene.add(shadowPlane);\nconst grad = new THREE.DataTexture(new Uint8Array([150,150,150,255, 215,215,215,255, 255,255,255,255]), 3, 1);\ngrad.minFilter = grad.magFilter = THREE.NearestFilter; grad.needsUpdate = true;\nlet idCounter = 1;\nfunction toon(color, extra = {}) { const m = new THREE.MeshToonMaterial({color, gradientMap: grad, ...extra}); m.userData.id = idCounter++; return m; }\nfunction idColorFor(n) { return new THREE.Color((n*0.618034)%1, ((n*0.381966)+.3)%1, ((n*0.2357)+.6)%1); }\nfunction smoothClosed(pts, n = 240) {\n  const c = new THREE.CatmullRomCurve3(pts.map(p => new THREE.Vector3(p[0], p[1], 0)), true, 'centripetal');\n  return c.getSpacedPoints(n).slice(0, -1).map(v => [v.x, v.y]);\n}\nfunction signedArea(p){let a=0;for(let i=0;i<p.length;i++){const[q,r]=p[i],[s,u]=p[(i+1)%p.length];a+=q*u-s*r;}return a/2;}\nfunction inset(poly, dfn) {\n  const s = Math.sign(signedArea(poly)); const n = poly.length;\n  return poly.map((p, i) => { const a = poly[(i-1+n)%n], b = poly[(i+1)%n];\n    let tx = b[0]-a[0], ty = b[1]-a[1]; const l = Math.hypot(tx,ty)||1; tx/=l; ty/=l; const d = dfn(p); return [p[0] - ty*s*d, p[1] + tx*s*d]; });\n}\nfunction clipAbove(poly, level) { const out = [];\n  for (let i = 0; i < poly.length; i++) { const a = poly[i], b = poly[(i+1)%poly.length]; const ina = a[1] >= level, inb = b[1] >= level;\n    if (ina) out.push(a); if (ina !== inb) { const k = (level - a[1]) / (b[1] - a[1]); out.push([a[0] + (b[0]-a[0])*k, level]); } }\n  return out; }\nconst shapeOf = poly => new THREE.Shape(poly.map(p => new THREE.Vector2(p[0], p[1])));\nconst extrude = (poly, depth, bevel = false) => new THREE.ExtrudeGeometry(shapeOf(poly), bevel ?\n  {depth, bevelEnabled:true, bevelThickness:0.04, bevelSize:0.035, bevelSegments:3, curveSegments:1} : {depth, bevelEnabled:false, curveSegments:1});\nconst COL = {ink:'#1d1b2a', teal:'#0f8f86', enamel:'#fbf6ea', dentin:'#f1d9a6', pulp:'#f08b86', gum:'#f3a1a6', gumRed:'#e2483d',\n  plaque:'#ead46f', tartar:'#c79d3e', caries:'#4b2c1c', skin:'#f1c09c', blue:'#2f5f86'};\nconst add = (o, parent) => { (parent || scene).add(o); o.traverse(c => { if (c.isMesh) c.castShadow = true; }); return o; };\n\n", 'chars': "// ------------------------------------------------ personajes (paciente y dentista)\nconst UPY = new THREE.Vector3(0, 1, 0);\nfunction bone(mesh, len0, p, q) {   // ubica una cápsula entre dos puntos (coordenadas del personaje)\n  const d = new THREE.Vector3().subVectors(q, p); const L = d.length();\n  mesh.position.copy(p).addScaledVector(d, 0.5); mesh.quaternion.setFromUnitVectors(UPY, d.normalize()); mesh.scale.set(1, L/len0, 1);\n}\nfunction makePerson(opt) {\n  const g = new THREE.Group();\n  const skin = toon(opt.skin), dark = toon('#2a1d1a'), white = toon('#ffffff'), shirt = toon(opt.shirt);\n  // torso con hombros (torno)\n  const prof = [[0,-3.2],[0.98,-3.2],[1.04,-2.4],[1.0,-1.7],[0.98,-1.25],[0.86,-0.95],[0.55,-0.78],[0.3,-0.72],[0,-0.7]].map(([r,y]) => new THREE.Vector2(r, y));\n  const torso = new THREE.Mesh(new THREE.LatheGeometry(prof, 40), shirt); torso.scale.z = 0.72; g.add(torso);\n  if (opt.coat) {\n    const v = new THREE.Mesh(extrude([[-0.34,0.0],[0.34,0.0],[0,-0.62]], 0.02), toon('#9fd3e6')); v.position.set(0, -0.76, 0.6); v.rotation.x = -0.35; g.add(v);\n    const pocket = new THREE.Mesh(new THREE.BoxGeometry(0.42, 0.34, 0.04), white); pocket.position.set(0.5, -1.55, 0.72); g.add(pocket);\n    const pen = new THREE.Mesh(new THREE.CylinderGeometry(0.035,0.035,0.4,10), toon(COL.teal)); pen.position.set(0.42,-1.32,0.76); g.add(pen);\n  } else {\n    const collar = new THREE.Mesh(new THREE.TorusGeometry(0.36, 0.07, 10, 30), toon('#ffffff')); collar.rotation.x = Math.PI/2 - 0.25; collar.position.set(0, -0.78, 0.05); collar.scale.z = 0.8; g.add(collar);\n  }\n  const neck = new THREE.Mesh(new THREE.CylinderGeometry(0.3, 0.34, 0.45, 20), skin); neck.position.y = -0.55; g.add(neck);\n  const head = new THREE.Group(); head.position.y = 0.45; g.add(head);\n  const skull = new THREE.Mesh(new THREE.SphereGeometry(1, 40, 28), skin); skull.scale.set(0.95, 1.02, 0.92); head.add(skull);\n  for (const s of [-1, 1]) { const ear = new THREE.Mesh(new THREE.SphereGeometry(0.19, 16, 12), skin); ear.position.set(0.9*s, 0.0, -0.05); ear.scale.set(0.55, 1, 0.8); head.add(ear); }\n  const hm = toon(opt.hair);\n  const hair = new THREE.Mesh(new THREE.SphereGeometry(1.05, 40, 20, 0, Math.PI*2, 0, opt.hairLen || 1.2), hm); hair.rotation.x = -0.42; hair.position.set(0, 0.06, -0.06); head.add(hair);\n  if (opt.long) for (const s of [-1, 1]) { const side = new THREE.Mesh(new THREE.CapsuleGeometry(0.28, 0.9, 6, 14), hm); side.position.set(0.82*s, -0.35, -0.25); side.rotation.z = 0.12*s; head.add(side); }\n  if (opt.bun) { const bun = new THREE.Mesh(new THREE.SphereGeometry(0.36, 20, 14), hm); bun.position.set(0, 0.98, -0.45); head.add(bun); }\n  if (opt.cap) { const cap = new THREE.Mesh(new THREE.SphereGeometry(1.08, 40, 20, 0, Math.PI*2, 0, 1.0), toon('#7cc5dd')); cap.rotation.x = -0.3; cap.position.y = 0.1; head.add(cap);\n}\n  const eyes = [];\n  for (const s of [-1, 1]) {\n    const e = new THREE.Mesh(new THREE.SphereGeometry(0.12, 16, 12), dark); e.position.set(0.32*s, 0.1, 0.85); e.scale.set(0.85, 1.2, 0.55); head.add(e); eyes.push(e);\n    const sh = new THREE.Mesh(new THREE.SphereGeometry(0.035, 8, 6), white); sh.position.set(0.32*s + 0.035, 0.16, 0.92); head.add(sh); e.userData.shine = sh;\n    const brow = new THREE.Mesh(new THREE.CapsuleGeometry(0.03, 0.18, 4, 8), dark); brow.rotation.z = Math.PI/2 - 0.15*s; brow.position.set(0.33*s, 0.36, 0.84); head.add(brow);\n    const cheek = new THREE.Mesh(new THREE.CircleGeometry(0.12, 20), new THREE.MeshBasicMaterial({color:'#f39a93', transparent:true, opacity:.5}));\n    cheek.material.userData.noOutline = true; cheek.position.set(0.53*s, -0.17, 0.76); cheek.rotation.y = 0.55*s; head.add(cheek);\n  }\n  const nose = new THREE.Mesh(new THREE.SphereGeometry(0.09, 14, 10), skin); nose.position.set(0, -0.06, 0.93); head.add(nose);\n  const mouth = new THREE.Group(); mouth.position.set(0, -0.42, 0.86); mouth.rotation.x = -0.28; head.add(mouth);\n  const mPoly = smoothClosed([[-0.32,0.06],[0,0.09],[0.32,0.06],[0.24,-0.13],[0,-0.22],[-0.24,-0.13]], 60);\n  mouth.add(new THREE.Mesh(extrude(mPoly, 0.02), toon('#7a2433')));\n  const m2 = new THREE.Mesh(extrude(clipAbove(mPoly.map(([x,y]) => [x*0.94, y]), -0.01), 0.02), white); m2.position.z = 0.012; mouth.add(m2);\n  const tg = new THREE.Mesh(extrude(smoothClosed([[-0.14,-0.11],[0.14,-0.11],[0.09,-0.19],[-0.09,-0.19]], 30), 0.02), toon('#e8707c')); tg.position.z = 0.01; mouth.add(tg);\n  if (opt.mask) { const mk = new THREE.Mesh(new THREE.BoxGeometry(0.9, 0.3, 0.1), toon('#9fd3e6')); mk.position.set(0, -0.9, 0.5); mk.rotation.x = 0.35; head.add(mk); }\n  // brazos articulados: hombro → codo → mano\n  const arms = {};\n  for (const [side, sx] of [['R', -1], ['L', 1]]) {\n    const sh = new THREE.Mesh(new THREE.SphereGeometry(0.25, 18, 14), shirt); sh.position.set(0.92*sx, -0.98, 0); g.add(sh);\n    const up = new THREE.Mesh(new THREE.CapsuleGeometry(0.21, 1, 6, 14), shirt); g.add(up);\n    const fo = new THREE.Mesh(new THREE.CapsuleGeometry(0.18, 1, 6, 14), opt.coat ? shirt : skin); g.add(fo);\n    const hand = new THREE.Mesh(new THREE.SphereGeometry(0.22, 18, 14), skin); g.add(hand);\n    arms[side] = {sh, up, fo, hand, set(el, hd) { const S = sh.position; bone(up, 1.42, S, el); bone(fo, 1.36, el, hd); hand.position.copy(hd); }};\n    arms[side].set(new THREE.Vector3(1.15*sx, -1.7, 0.15), new THREE.Vector3(1.12*sx, -2.4, 0.35));\n  }\n  g.userData = {head, eyes, arms, mouth};\n  return g;\n}\n\n", 'outline': '// ------------------------------------------------ contorno de tinta (ID + profundidad)\nconst rtBeauty = new THREE.WebGLRenderTarget(W, H, {samples:4});\nconst rtId = new THREE.WebGLRenderTarget(W, H); rtId.depthTexture = new THREE.DepthTexture(W, H);\nconst post = new THREE.Mesh(new THREE.PlaneGeometry(2,2), new THREE.ShaderMaterial({\n  uniforms:{tBeauty:{value:rtBeauty.texture}, tId:{value:rtId.texture}, tDepth:{value:rtId.depthTexture}, res:{value:new THREE.Vector2(W,H)},\n    ink:{value:new THREE.Color(COL.ink)}, near:{value:.1}, far:{value:100}, thick:{value:2.2*SC}},\n  vertexShader:`varying vec2 vUv; void main(){vUv=uv; gl_Position=vec4(position.xy,0.,1.);}`,\n  fragmentShader:`uniform sampler2D tBeauty,tId,tDepth; uniform vec2 res; uniform vec3 ink; uniform float near,far,thick; varying vec2 vUv;\n    float lin(float d){ float z=d*2.-1.; return (2.*near*far)/(far+near-z*(far-near)); }\n    void main(){ vec2 px = thick/res; vec3 c0 = texture2D(tId,vUv).rgb; float d0 = lin(texture2D(tDepth,vUv).r); float e = 0.;\n      for(int i=0;i<8;i++){ float a = float(i)*0.785398; vec2 o = vec2(cos(a),sin(a))*px;\n        vec3 c = texture2D(tId,vUv+o).rgb; float d = lin(texture2D(tDepth,vUv+o).r);\n        e = max(e, step(0.02, distance(c,c0))); e = max(e, step(0.06*min(d,d0), abs(d-d0))); }\n      vec3 col = texture2D(tBeauty,vUv).rgb; gl_FragColor = vec4(mix(col, ink, e*0.92), 1.);\n      #include <colorspace_fragment>\n    }`}));\nconst postScene = new THREE.Scene(); postScene.add(post); const postCam = new THREE.OrthographicCamera(-1,1,1,-1,0,1);\nconst idMats = new Map();\nconst idMat = m => { if (!idMats.has(m)) idMats.set(m, new THREE.MeshBasicMaterial({color: idColorFor(m.userData.id || 99)})); return idMats.get(m); };\nfunction twoLayers(target) {\n  renderer.setRenderTarget(target); renderer.autoClear = true; renderer.render(scene, camera);\n  renderer.autoClear = false; renderer.clearDepth(); renderer.render(frontScene, camera); renderer.autoClear = true;\n}\nfunction renderAll() {\n  hemi2.intensity = hemi.intensity; sun2.intensity = sun.intensity;\n  twoLayers(rtBeauty);\n  const saved = []; const bgSave = scene.background; scene.background = new THREE.Color(0,0,0);\n  for (const sc of [scene, frontScene]) sc.traverse(o => { if (!o.isMesh) return; saved.push([o, o.material, o.visible]);\n    if (o.material.userData.noOutline || o === shadowPlane) { o.visible = false; return; } o.material = idMat(o.material); });\n  twoLayers(rtId);\n  for (const [o, m, v] of saved) { o.material = m; o.visible = v; }\n  scene.background = bgSave; renderer.setRenderTarget(null); renderer.render(postScene, postCam);\n}\n\n', 'chunks': "// palabras con su instante (proporcional a las sílabas) y bloques de 2-5 palabras\nconst syl = w => Math.max(1, (w.toLowerCase().match(/[aeiouáéíóú]+/g) || []).length);\nconst CHUNKS = [];\nLINES.forEach((line, li) => {\n  const words = line.split(' '); const [a, b] = B[li];\n  const tot = words.reduce((s, w) => s + syl(w) + (/[,:.?]$/.test(w) ? 1 : 0), 0);\n  let acc = 0; const times = words.map(w => { const t = a + (b - a) * acc / tot; acc += syl(w) + (/[,:.?]$/.test(w) ? 1 : 0); return t; });\n  let cur = [];\n  words.forEach((w, i) => {\n    cur.push(i);\n    const end = /[,:.?]$/.test(w) && cur.length >= 2 || cur.length >= 4 || i === words.length - 1;\n    if (end) { CHUNKS.push({li, idx: cur.slice(), words, times}); cur = []; }\n  });\n});\nCHUNKS.forEach((c, i) => {\n  c.t0 = c.times[c.idx[0]];\n  const nx = CHUNKS[i + 1];\n  c.t1 = nx && nx.li === c.li ? nx.times[nx.idx[0]] : B[c.li][1] + (nx ? Math.min(0.15, nx.times[nx.idx[0]] - B[c.li][1]) : 0.4);\n});\n\n"}